    if bar is None:
        return out
    top = grid[0]
    bottom = grid[-1]
    top_cols = {c for c, v in enumerate(top) if v != 0}
    bottom_cols = {c for c, v in enumerate(bottom) if v != 0}
    for c in top_cols & bottom_cols:
        for r in range(1, bar):
            if out[r][c] == 0:
                out[r][c] = 4
    return out
